export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  maxNights: number;
  maxGuests: number;
  base: number;          // per-night rate
  highAdd: number;       // per-night premium in high season
  minNights?: number;    // villa minimum stay
  flat?: number;         // villa flat surcharge
  guestFeeCap?: number;  // suite: surcharge applies above this guest count
  guestFee?: number;     // suite surcharge
  prefix: string;        // line label
}

