export interface QuoteResult { ok: boolean; error?: string; total?: number; policy?: string; line?: string; }
interface CategoryConfig { maxNights: number; maxGuests: number; base: number; highAdd: number; minNights?: number; flat?: number; guestFeeCap?: number; guestFee?: number; prefix: string; }
const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { maxNights: 14, maxGuests: 2, base: 80, highAdd: 30, prefix: "standard" },
  suite:    { maxNights: 21, maxGuests: 4, base: 150, highAdd: 60, guestFeeCap: 2, guestFee: 25, prefix: "suite" },
  villa:    { maxNights: 28, maxGuests: 8, base: 300, highAdd: 120, minNights: 3, flat: 500, prefix: "villa" },
};
export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed request" };
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) return { ok: false, error: "bad loyalty" };
  const cfg = CATEGORIES[req.category];
  if (!cfg) return { ok: false, error: "unknown category" };
  const nights = req.nights as number; const guests = req.guests as number; const loyalty = req.loyaltyYears as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) return { ok: false, error: "bad nights" };
  if (cfg.minNights && nights < cfg.minNights) return { ok: false, error: "villa minimum stay" };
  if (!Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests) return { ok: false, error: "bad guests" };
  if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
  let total = cfg.base * nights;
  if (req.season === "high") total += cfg.highAdd * nights;
  const vipOrSenior = req.coupon === "VIP" || loyalty >= 3;
  if (vipOrSenior) total -= Math.floor(total / 10);
  if (cfg.flat) total += cfg.flat;
  if (cfg.guestFee && guests > cfg.guestFeeCap) total += cfg.guestFee;
  const policy = vipOrSenior ? "flex" : "strict";
  const line = cfg.prefix + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}
EOF
