    return { ok: false, error: "bad season" };
  }

  let total = cfg.base * nights;
  if (req.season === "high") {
    total += cfg.highAdd * nights;
  }

  const vipOrSenior = req.coupon === "VIP" || loyalty >= 3;
  if (vipOrSenior) {
    total -= Math.floor(total / 10);
  }
  if (cfg.flat) {
    total += cfg.flat;
  }
  if (cfg.guestFee && guests > cfg.guestFeeCap) {
    total += cfg.guestFee;
  }

  const policy = vipOrSenior ? "flex" : "strict";
  const line = cfg.prefix + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

